<template>
  <div class="docnet-agents-page q-gutter-y-md">
    <div class="page-header">
      <h2 class="page-title">{{ $t('docnet_agents_page_title') }}</h2>
      <p class="page-subtitle text-grey-7">
        {{ $t('docnet_agents_page_subtitle') }}
      </p>
    </div>

    <!-- Routes section: per-org code_prefix → agent_key mapping -->
    <q-card flat bordered class="routes-card" data-test="routes-card">
      <q-card-section class="row items-center q-pa-md">
        <q-icon name="mdi:routes" size="22px" color="primary" class="q-mr-md" />
        <div>
          <div class="section-title">{{ $t('docnet_routes_title') }}</div>
          <div class="section-subtitle text-grey-7">
            {{ $t('docnet_routes_subtitle') }}
          </div>
        </div>
        <q-space />
        <q-btn
          v-if="missingDefaultsCount > 0"
          flat
          no-caps
          size="sm"
          color="primary"
          icon="mdi:auto-fix"
          :label="`${$t('docnet_suggest_defaults')} (${missingDefaultsCount})`"
          data-test="suggest-defaults"
          @click="suggestDefaults"
        />
        <q-btn
          unelevated
          no-caps
          color="primary"
          icon="add"
          :label="$t('docnet_add_route')"
          data-test="add-route"
          @click="openAddDialog"
        />
      </q-card-section>

      <q-separator />

      <q-card-section class="q-pa-none">
        <q-table
          :rows="routes"
          :columns="routeColumns"
          row-key="id"
          :loading="loadingRoutes"
          flat
          hide-pagination
          :rows-per-page-options="[0]"
          data-test="routes-table"
        >
          <template #no-data>
            <div class="empty-state">
              <q-icon name="mdi:routes" size="32px" color="grey-5" />
              <div class="text-grey-7 q-mt-sm">
                {{ $t('docnet_routes_empty_state') }}
              </div>
            </div>
          </template>

          <template #body-cell-code_prefix="{ row }">
            <q-td>
              <code class="prefix-code" :data-test="`route-prefix-${row.id}`">
                {{ row.code_prefix }}
              </code>
            </q-td>
          </template>

          <template #body-cell-agent_key="{ row }">
            <q-td>
              <div class="agent-cell" :data-test="`route-agent-${row.id}`">
                <span class="agent-label">{{ agentLabel(row.agent_key) }}</span>
                <q-icon
                  v-if="!agentByKey[row.agent_key]"
                  name="warning"
                  color="amber-7"
                  size="16px"
                  class="q-ml-xs"
                  :title="$t('docnet_agent_unknown_warn')"
                />
              </div>
            </q-td>
          </template>

          <template #body-cell-enabled="{ row }">
            <q-td>
              <q-toggle
                :model-value="row.enabled"
                color="primary"
                :data-test="`route-enabled-${row.id}`"
                @update:model-value="(v: boolean) => onToggleEnabled(row, v)"
              />
            </q-td>
          </template>

          <template #body-cell-actions="{ row }">
            <q-td>
              <q-btn
                flat
                dense
                round
                size="sm"
                icon="edit"
                color="primary"
                :title="$t('edit')"
                :data-test="`route-edit-${row.id}`"
                @click="openEditDialog(row)"
              />
              <q-btn
                flat
                dense
                round
                size="sm"
                icon="delete"
                color="negative"
                :title="$t('delete')"
                :data-test="`route-delete-${row.id}`"
                @click="onDelete(row)"
              />
            </q-td>
          </template>
        </q-table>
      </q-card-section>
    </q-card>

    <!-- Agents registry: read-only -->
    <q-card flat bordered class="agents-card" data-test="agents-card">
      <q-card-section class="row items-center q-pa-md">
        <q-icon name="mdi:robot-outline" size="22px" color="primary" class="q-mr-md" />
        <div>
          <div class="section-title">{{ $t('docnet_agents_title') }}</div>
          <div class="section-subtitle text-grey-7">
            {{ $t('docnet_agents_subtitle') }}
          </div>
        </div>
      </q-card-section>

      <q-separator />

      <q-card-section
        v-if="loadingAgents"
        class="q-pa-md text-center text-grey-7"
      >
        <q-spinner color="primary" size="24px" />
      </q-card-section>

      <q-card-section v-else class="agents-grid q-pa-md">
        <div
          v-for="agent in agents"
          :key="agent.agent_key"
          class="agent-card"
          :data-test="`agent-card-${agent.agent_key}`"
        >
          <div class="agent-card-header">
            <q-chip
              dense
              square
              color="primary"
              text-color="white"
              class="agent-key-chip"
            >
              {{ agent.agent_key }}
            </q-chip>
            <span class="agent-label">{{ agent.label }}</span>
          </div>
          <div class="agent-description">{{ agent.description }}</div>
          <div class="agent-meta">
            <div class="meta-row">
              <span class="meta-label">{{ $t('docnet_celery_task') }}:</span>
              <code>{{ agent.celery_task }}</code>
            </div>
            <div class="meta-row">
              <span class="meta-label">{{ $t('docnet_default_prefixes') }}:</span>
              <q-chip
                v-for="prefix in agent.default_code_prefixes"
                :key="prefix"
                dense
                square
                color="grey-3"
                text-color="grey-9"
                class="prefix-chip"
              >
                <code>{{ prefix }}</code>
              </q-chip>
            </div>
          </div>
        </div>
      </q-card-section>
    </q-card>

    <!-- Add / Edit dialog -->
    <q-dialog v-model="dialogOpen" no-backdrop-dismiss>
      <q-card class="route-dialog" data-test="route-dialog">
        <q-card-section>
          <div class="text-h6">
            {{ editingRoute ? $t('docnet_edit_route') : $t('docnet_add_route') }}
          </div>
        </q-card-section>
        <q-separator />
        <q-card-section class="q-gutter-y-md">
          <q-input
            outlined
            dense
            v-model="dialogForm.code_prefix"
            :label="$t('docnet_route_code_prefix')"
            :hint="$t('docnet_route_code_prefix_hint')"
            :readonly="!!editingRoute"
            data-test="dialog-code-prefix"
          />
          <q-select
            outlined
            dense
            v-model="dialogForm.agent_key"
            :options="agentOptions"
            :label="$t('docnet_route_agent_key')"
            emit-value
            map-options
            data-test="dialog-agent-key"
          />
          <q-toggle
            v-model="dialogForm.enabled"
            :label="$t('docnet_route_enabled')"
            data-test="dialog-enabled"
          />
        </q-card-section>
        <q-separator />
        <q-card-actions align="right" class="q-pa-md">
          <q-btn
            flat
            no-caps
            :label="$t('cancel')"
            data-test="dialog-cancel"
            @click="dialogOpen = false"
          />
          <q-btn
            unelevated
            no-caps
            color="primary"
            :label="$t('save')"
            :loading="dialogSaving"
            :disable="!dialogForm.code_prefix || !dialogForm.agent_key"
            data-test="dialog-save"
            @click="onDialogSave"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions/index';
import { notificationRoutingApiService } from 'src/services';
import type {
  AgentRegistryEntry,
  NotificationRoute,
} from 'src/services/settings/NotificationRoutingApiService';

interface DialogForm {
  code_prefix: string;
  agent_key: string;
  enabled: boolean;
}

export default defineComponent({
  name: 'DocNetAgentsList',
  data() {
    return {
      loadingAgents: false,
      loadingRoutes: false,
      agents: [] as AgentRegistryEntry[],
      routes: [] as NotificationRoute[],
      dialogOpen: false,
      dialogSaving: false,
      editingRoute: null as NotificationRoute | null,
      dialogForm: {
        code_prefix: '',
        agent_key: '',
        enabled: true,
      } as DialogForm,
    };
  },
  computed: {
    agentByKey(): Record<string, AgentRegistryEntry> {
      const out: Record<string, AgentRegistryEntry> = {};
      for (const a of this.agents) out[a.agent_key] = a;
      return out;
    },
    agentOptions() {
      return this.agents.map((a) => ({
        label: `${a.label} (${a.agent_key})`,
        value: a.agent_key,
      }));
    },
    routeColumns(): any[] {
      return [
        {
          name: 'code_prefix',
          label: this.$t('docnet_route_code_prefix'),
          field: 'code_prefix',
          align: 'left',
        },
        {
          name: 'agent_key',
          label: this.$t('docnet_route_agent_key'),
          field: 'agent_key',
          align: 'left',
        },
        {
          name: 'enabled',
          label: this.$t('docnet_route_enabled'),
          field: 'enabled',
          align: 'center',
          style: 'width: 100px',
        },
        {
          name: 'actions',
          label: '',
          field: () => '',
          align: 'right',
          style: 'width: 100px',
        },
      ];
    },
    /** Agents whose default_code_prefixes are not yet covered by any
     *  configured route. Powers the "Suggest defaults" button so an
     *  admin can one-click bootstrap a sane initial mapping. */
    missingDefaultsCount(): number {
      const existing = new Set(this.routes.map((r) => r.code_prefix));
      let count = 0;
      for (const agent of this.agents) {
        for (const prefix of agent.default_code_prefixes) {
          if (!existing.has(prefix)) count += 1;
        }
      }
      return count;
    },
  },
  mounted() {
    this.loadAll();
  },
  methods: {
    agentLabel(key: string): string {
      return this.agentByKey[key]?.label || key;
    },
    async loadAll() {
      this.loadingAgents = true;
      this.loadingRoutes = true;
      try {
        const [agentsResp, routesResp] = await Promise.all([
          notificationRoutingApiService.listAgents(),
          notificationRoutingApiService.listRoutes(),
        ]);
        this.agents = agentsResp?.agents || [];
        this.routes = routesResp?.routes || [];
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.loadingAgents = false;
        this.loadingRoutes = false;
      }
    },
    openAddDialog() {
      this.editingRoute = null;
      this.dialogForm = {
        code_prefix: '',
        agent_key: this.agents[0]?.agent_key || '',
        enabled: true,
      };
      this.dialogOpen = true;
    },
    openEditDialog(row: NotificationRoute) {
      this.editingRoute = row;
      this.dialogForm = {
        code_prefix: row.code_prefix,
        agent_key: row.agent_key,
        enabled: row.enabled,
      };
      this.dialogOpen = true;
    },
    async onDialogSave() {
      this.dialogSaving = true;
      try {
        await notificationRoutingApiService.upsertRoute(
          this.dialogForm.code_prefix.trim(),
          this.dialogForm.agent_key,
          this.dialogForm.enabled,
        );
        notify.success(this.$t('docnet_route_saved'));
        this.dialogOpen = false;
        await this.loadAll();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.dialogSaving = false;
      }
    },
    async onToggleEnabled(row: NotificationRoute, value: boolean) {
      const prev = row.enabled;
      row.enabled = value;
      try {
        await notificationRoutingApiService.upsertRoute(
          row.code_prefix,
          row.agent_key,
          value,
        );
      } catch (err) {
        row.enabled = prev;
        notify.error(ApiExceptions.getErrorMessage(err as any));
      }
    },
    async onDelete(row: NotificationRoute) {
      const confirmed = window.confirm(
        this.$t('docnet_route_delete_confirm', {
          prefix: row.code_prefix,
        }),
      );
      if (!confirmed) return;
      try {
        await notificationRoutingApiService.deleteRoute(row.code_prefix);
        notify.success(this.$t('docnet_route_deleted'));
        this.routes = this.routes.filter((r) => r.id !== row.id);
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      }
    },
    async suggestDefaults() {
      const existing = new Set(this.routes.map((r) => r.code_prefix));
      const additions: { prefix: string; agent_key: string }[] = [];
      for (const agent of this.agents) {
        for (const prefix of agent.default_code_prefixes) {
          if (!existing.has(prefix)) {
            additions.push({ prefix, agent_key: agent.agent_key });
          }
        }
      }
      if (additions.length === 0) return;
      let failed = 0;
      for (const a of additions) {
        try {
          await notificationRoutingApiService.upsertRoute(
            a.prefix,
            a.agent_key,
            true,
          );
        } catch {
          failed += 1;
        }
      }
      if (failed === 0) {
        notify.success(
          this.$t('docnet_suggest_defaults_success', {
            count: additions.length,
          }),
        );
      } else {
        notify.error(
          this.$t('docnet_suggest_defaults_partial', {
            failed,
            total: additions.length,
          }),
        );
      }
      await this.loadAll();
    },
  },
});
</script>

